-- V11: the complete commodity known list and the price units shown by the official reports (owner module: commodity).
--
-- * Known list (ADR-0006 item 2): the Agmarknet 2.0 (DMI) commodity master, 605 names in 16 commodity groups, read
--   from the public filter data of the Daily Price and Arrival report (api.agmarknet.gov.in
--   /v1/daily-price-arrival/filters, retrieved 2026-10-15; docs/data/raw/Agmarknet_daily-price-arrival_filters_2026-10-15.json).
--   Names are whitespace-normalized (three master names carry a trailing space or newline); category is the official
--   commodity-group name. The 53 commodities of V8 are already present and are left unchanged.
-- * Units (ADR-0008 item 1): set only where an official export states the unit for that commodity: the 17
--   Agmarknet 2.0 'Commodity-wise, Market-wise Daily Report (Weighted Average)' exports for report date
--   13-Oct-2026, all states, all 16 commodity groups (docs/data/raw/Commodity-wise_Market-wise_Daily_Weighted_Avg_
--   Report_15-10-2026_*.csv, exported by the project owner on 2026-10-15). Every data row carries 'Unit of Price';
--   no commodity shows more than one unit. The unit is stored in the source's notation: most commodities are
--   'Rs./Quintal', some flowers, livestock and others are 'Rs./Unit', and Coriander(Leaves), Mint(Pudina) and
--   Leafy Vegetable are 'Rs./Bundle'. Nothing is converted (ADR-0008 item 3); comparison and alerts accept only
--   'Rs./Quintal' (ADR-0023). The Maharashtra rows of these exports were matched to the data.gov.in historical
--   records of the same date: 1,287 of 1,292 rows with the same market, variety and grade have the same modal price.
-- * Commodities of the master that had no rows on 13-Oct-2026 keep price_unit NULL; ingestion rejects their records
--   as UNIT_UNVERIFIED until official evidence is recorded (ADR-0008 item 2, ADR-0020).
-- Every statement is keyed on the commodity name and changes only rows without a unit, so re-running changes nothing.

ON CONFLICT (canonical_name) DO NOTHING;

UPDATE commodities c
SET price_unit = v.price_unit, price_unit_source = v.price_unit_source
FROM (VALUES
    ('Absinthe', 'Rs./Quintal', 'Agmarknet 2.0 (DMI) export ''Commodity-wise, Market-wise Daily Report (Weighted Average)'', report date 13-Oct-2026, column Unit of Price = Rs./Quintal (docs/data/raw/Commodity-wise_Market-wise_Daily_Weighted_Avg_Report_15-10-2026_02-22-47_AM.csv)'),
